/**
 * Postgres implementation of ScorerStore over the shared Drizzle schema (packages/db).
 *
 * Reads: only rows with provenance LIVE, TESTNET or BASELINE describe the real book; MOCK,
 * SIMULATED and BACKTEST rows never feed a score. The baseline spread for a market is the mean
 * of its BASELINE snapshots taken before the first STRATA agent order in that market (PRD 10.4).
 * Arena markets and their uptime spread limit come from @strata/config (generated by the live
 * market fetch). Funding payments and bank-transfer history are not stored yet, so funding is 0
 * and funding-source WASH linking has no edges until the indexer records them (docs/SCORING.md).
 */
import { and, asc, eq, gte, inArray, isNull, lt, max, or, gt, sql } from "drizzle-orm";
import type { Hex } from "viem";
import { z } from "zod";
import { getMarkets } from "@strata/config";
import { agentFills, agentOrders, agents, bookSnapshots, epochRuns, epochs, heartbeats, scores, type Db } from "@strata/db";
import { AgentStatus, Side, type NetworkName } from "@strata/sdk";
import type { EpochData, SeasonInfo } from "./epoch.js";
import { BOOK_STALENESS_MS, MARKOUT_HORIZON_MS } from "./metrics.js";
import type { AgentRecord, BookSample, EpochWindow, FillRecord, MarketParams, MarkPoint, OrderRecord } from "./model.js";
import type { EpochRun, RunStatus, SaveScoredArgs, ScorerStore } from "./runner.js";

const SCORING_PROVENANCE = ["LIVE", "TESTNET", "BASELINE"] as const;
const RUN_STATUS = z.enum(["computed", "submitted", "posted", "skipped", "failed"]);
const MarketIds = z.array(z.string());
const HexString = z.string().regex(/^0x[0-9a-fA-F]+$/);

const ms = (d: Date) => d.getTime();
const num = (v: string | null): number | null => (v === null ? null : Number(v));

export function arenaMarkets(network: NetworkName): MarketParams[] {
  return getMarkets(network)
    .filter((m) => m.arenaEnabled)
    .map((m) => ({ marketId: m.marketId.toLowerCase(), maxSpreadBps: m.maxSpreadBps }));
}

export class PgScorerStore implements ScorerStore {
  constructor(
    private readonly db: Db,
    private readonly network: NetworkName,
    private readonly markets: readonly MarketParams[] = arenaMarkets(network),
  ) {}

  async loadEpochData(window: EpochWindow, season: SeasonInfo): Promise<EpochData> {
    const { db, network } = this;
    const marketIds = this.markets.map((m) => m.marketId);
    const agentRows = await db.select().from(agents).where(eq(agents.network, network));
    const agentList: AgentRecord[] = agentRows.map((r) => ({
      agentId: r.agentId,
      operator: r.operator.toLowerCase(),
      subaccountId: r.subaccountId.toLowerCase(),
      status: AgentStatus.parse(r.status),
      marketIds: MarketIds.parse(r.marketIds).map((id) => id.toLowerCase()),
      simulated: r.simulated,
      enrolledAt: ms(r.enrolledAt),
    }));
    const agentIds = agentList.map((a) => a.agentId);
    const base: EpochData = {
      network,
      window,
      agents: agentList,
      markets: this.markets,
      book: new Map(),
      baselineSpreadBps: new Map(),
      orders: [],
      fills: [],
      funding: [],
      marks: new Map(),
      fundingEdges: [],
    };
    if (marketIds.length === 0 || agentIds.length === 0) return base;

    const bookFrom = new Date(window.startMs - BOOK_STALENESS_MS);
    const bookTo = new Date(window.endMs + MARKOUT_HORIZON_MS + BOOK_STALENESS_MS);
    const bookRows = await db
      .select({ marketId: bookSnapshots.marketId, at: bookSnapshots.at, mid: bookSnapshots.mid, spreadBps: bookSnapshots.spreadBps, depthUsd25: bookSnapshots.depthUsd25 })
      .from(bookSnapshots)
      .where(
        and(
          eq(bookSnapshots.network, network),
          inArray(sql`lower(${bookSnapshots.marketId})`, marketIds),
          inArray(bookSnapshots.provenance, [...SCORING_PROVENANCE]),
          gte(bookSnapshots.at, bookFrom),
          lt(bookSnapshots.at, bookTo),
        ),
      )
      .orderBy(asc(bookSnapshots.at));
    const book = new Map<string, BookSample[]>();
    for (const r of bookRows) {
      const id = r.marketId.toLowerCase();
      const list = book.get(id) ?? [];
      list.push({ at: ms(r.at), mid: num(r.mid), spreadBps: r.spreadBps, depthUsd25: r.depthUsd25 });
      book.set(id, list);
    }

    const baselineSpreadBps = new Map<string, number>();
    for (const marketId of marketIds) {
      const [row] = await db.execute<{ spread: number | null }>(sql`
        SELECT avg(spread_bps)::float8 AS spread FROM book_snapshots
        WHERE network = ${network} AND lower(market_id) = ${marketId} AND provenance = 'BASELINE' AND spread_bps IS NOT NULL
          AND at < coalesce((SELECT min(posted_at) FROM agent_orders WHERE network = ${network} AND lower(market_id) = ${marketId}), 'infinity'::timestamptz)`);
      if (row?.spread !== null && row?.spread !== undefined) baselineSpreadBps.set(marketId, Number(row.spread));
    }

    const orderRows = await db
      .select()
      .from(agentOrders)
      .where(
        and(
          eq(agentOrders.network, network),
          inArray(agentOrders.agentId, agentIds),
          inArray(sql`lower(${agentOrders.marketId})`, marketIds),
          inArray(agentOrders.provenance, ["LIVE", "TESTNET"]),
          lt(agentOrders.postedAt, new Date(window.endMs)),
          or(isNull(agentOrders.cancelledAt), gt(agentOrders.cancelledAt, new Date(window.startMs))),
        ),
      );
    const orders: OrderRecord[] = orderRows.map((r) => ({
      agentId: r.agentId,
      marketId: r.marketId.toLowerCase(),
      orderHash: r.orderHash,
      side: Side.parse(r.side),
      price: Number(r.price),
      quantity: Number(r.quantity),
      postedAt: ms(r.postedAt),
      cancelledAt: r.cancelledAt ? ms(r.cancelledAt) : null,
    }));

    const fillRows = await db
      .select()
      .from(agentFills)
      .where(
        and(
          eq(agentFills.network, network),
          inArray(agentFills.agentId, agentIds),
          inArray(agentFills.provenance, ["LIVE", "TESTNET"]),
          gte(agentFills.executedAt, new Date(season.startMs)),
          lt(agentFills.executedAt, new Date(window.endMs)),
        ),
      )
      .orderBy(asc(agentFills.executedAt), asc(agentFills.txHash), asc(agentFills.eventIndex));
    const fills: FillRecord[] = fillRows.map((r) => ({
      id: `${r.txHash.toLowerCase()}:${r.eventIndex}`,
      agentId: r.agentId,
      marketId: r.marketId.toLowerCase(),
      orderHash: r.orderHash,
      side: Side.parse(r.side),
      price: Number(r.price),
      quantity: Number(r.quantity),
      feeUsd: r.feeUsd,
      isMaker: r.isMaker,
      counterpartySubaccountId: r.counterpartySubaccountId ? r.counterpartySubaccountId.toLowerCase() : null,
      executedAt: ms(r.executedAt),
    }));

    // Equity marks: one per minute before the epoch (keeps a month-long season cheap), every sample inside it.
    const markRows = await db.execute<{ market_id: string; at: Date | string; mid: string }>(sql`
      SELECT DISTINCT ON (lower(market_id), date_trunc('minute', at)) lower(market_id) AS market_id, at, mid
      FROM book_snapshots
      WHERE network = ${network} AND lower(market_id) IN ${marketIds} AND provenance IN ('LIVE', 'TESTNET', 'BASELINE')
        AND mid IS NOT NULL AND at >= ${new Date(season.startMs).toISOString()} AND at < ${new Date(window.startMs).toISOString()}
      ORDER BY lower(market_id), date_trunc('minute', at), at DESC`);
    const marks = new Map<string, MarkPoint[]>();
    for (const r of markRows) {
      const list = marks.get(r.market_id) ?? [];
      list.push({ at: new Date(r.at).getTime(), mid: Number(r.mid) });
      marks.set(r.market_id, list);
    }
    for (const [marketId, samples] of book) {
      const list = marks.get(marketId) ?? [];
      for (const b of samples) if (b.mid !== null && b.at >= window.startMs && b.at < window.endMs) list.push({ at: b.at, mid: b.mid });
      marks.set(marketId, list);
    }

    return { ...base, book, baselineSpreadBps, orders, fills, marks };
  }

  async getRun(season: number, epoch: number): Promise<EpochRun | null> {
    const [r] = await this.db
      .select()
      .from(epochRuns)
      .where(and(eq(epochRuns.network, this.network), eq(epochRuns.season, season), eq(epochRuns.epoch, epoch)));
    if (!r) return null;
    return {
      season: r.season,
      epoch: r.epoch,
      status: RUN_STATUS.parse(r.status),
      merkleRoot: r.merkleRoot ? (HexString.parse(r.merkleRoot) as Hex) : null,
      dataUri: r.dataUri,
      txHash: r.txHash ? (HexString.parse(r.txHash) as Hex) : null,
      reason: r.reason,
      attempts: r.attempts,
    };
  }

  async nextEpochToProcess(season: number, settled: readonly RunStatus[]): Promise<number> {
    const [r] = await this.db
      .select({ last: max(epochRuns.epoch) })
      .from(epochRuns)
      .where(and(eq(epochRuns.network, this.network), eq(epochRuns.season, season), inArray(epochRuns.status, [...settled])));
    return r?.last === null || r?.last === undefined ? 0 : r.last + 1;
  }

  async saveScored(args: SaveScoredArgs): Promise<void> {
    const { window } = args;
    const network = this.network;
    const now = new Date();
    await this.db.transaction(async (tx) => {
      await tx
        .insert(epochs)
        .values({
          network,
          season: window.season,
          epoch: window.epoch,
          startTime: new Date(window.startMs),
          endTime: new Date(window.endMs),
          merkleRoot: args.merkleRoot,
          dataUri: args.dataUri,
          txHash: null,
          postedAt: null,
          contract: args.contract,
        })
        .onConflictDoUpdate({
          target: [epochs.network, epochs.season, epochs.epoch],
          set: { startTime: new Date(window.startMs), endTime: new Date(window.endMs), merkleRoot: args.merkleRoot, dataUri: args.dataUri, contract: args.contract },
          setWhere: isNull(epochs.txHash),
        });
      await tx.delete(scores).where(and(eq(scores.network, network), eq(scores.season, window.season), eq(scores.epoch, window.epoch)));
      await tx.insert(scores).values(
        args.scores.map((s) => ({
          network,
          season: s.season,
          epoch: s.epoch,
          agentId: s.agentId,
          score: s.score,
          metrics: s.metrics,
          flags: s.flags,
          leaf: s.leaf,
          proof: s.proof,
          provenance: s.provenance,
        })),
      );
      const detail = { documentHash: args.documentHash, flagNames: Object.fromEntries(args.scores.map((s) => [s.agentId, s.flagNames])), evidence: args.evidence, breakdown: args.breakdown };
      await tx
        .insert(epochRuns)
        .values({ network, season: window.season, epoch: window.epoch, status: "computed", merkleRoot: args.merkleRoot, dataUri: args.dataUri, documentHash: args.documentHash, txHash: null, reason: null, attempts: 0, detail, updatedAt: now })
        .onConflictDoUpdate({
          target: [epochRuns.network, epochRuns.season, epochRuns.epoch],
          set: { status: "computed", merkleRoot: args.merkleRoot, dataUri: args.dataUri, documentHash: args.documentHash, reason: null, detail, updatedAt: now },
        });
    });
  }

  async recordSubmitted(season: number, epoch: number, txHash: Hex): Promise<void> {
    await this.db.transaction(async (tx) => {
      await tx.update(epochs).set({ txHash }).where(and(eq(epochs.network, this.network), eq(epochs.season, season), eq(epochs.epoch, epoch)));
      await this.upsertRun(tx, season, epoch, { status: "submitted", txHash, attempts: 0, reason: null });
    });
  }

  async recordPosted(season: number, epoch: number, txHash: Hex | null, postedAtMs: number): Promise<void> {
    await this.db.transaction(async (tx) => {
      await tx
        .update(epochs)
        .set({ postedAt: new Date(postedAtMs), ...(txHash ? { txHash } : {}) })
        .where(and(eq(epochs.network, this.network), eq(epochs.season, season), eq(epochs.epoch, epoch)));
      await this.upsertRun(tx, season, epoch, { status: "posted", reason: null, ...(txHash ? { txHash } : {}) });
    });
  }

  async recordSkipped(season: number, epoch: number, reason: string): Promise<void> {
    await this.upsertRun(this.db, season, epoch, { status: "skipped", reason });
  }

  async recordFailure(season: number, epoch: number, reason: string): Promise<void> {
    await this.upsertRun(this.db, season, epoch, { status: "failed", reason }, true);
  }

  /** Liveness row for /status (PRD 11.2). */
  async heartbeat(detail: Record<string, unknown>): Promise<void> {
    const at = new Date();
    await this.db
      .insert(heartbeats)
      .values({ network: this.network, service: "scorer", at, detail })
      .onConflictDoUpdate({ target: [heartbeats.network, heartbeats.service], set: { at, detail } });
  }

  private async upsertRun(
    db: Pick<Db, "insert">,
    season: number,
    epoch: number,
    patch: { status: RunStatus; reason: string | null; txHash?: Hex; attempts?: number },
    incrementAttempts = false,
  ): Promise<void> {
    const now = new Date();
    await db
      .insert(epochRuns)
      .values({ network: this.network, season, epoch, status: patch.status, reason: patch.reason, txHash: patch.txHash ?? null, attempts: incrementAttempts ? 1 : (patch.attempts ?? 0), detail: {}, updatedAt: now })
      .onConflictDoUpdate({
        target: [epochRuns.network, epochRuns.season, epochRuns.epoch],
        set: {
          status: patch.status,
          reason: patch.reason,
          updatedAt: now,
          ...(patch.txHash ? { txHash: patch.txHash } : {}),
          ...(incrementAttempts ? { attempts: sql`${epochRuns.attempts} + 1` } : patch.attempts !== undefined ? { attempts: patch.attempts } : {}),
        },
      });
  }
}
